<span class="line">                    timeRange <span class="token operator">=</span> timeData<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token operator">+</span> <span class="token string">&quot;至&quot;</span> <span class="token operator">+</span> timeData<span class="token punctuation">[</span>timeData<span class="token punctuation">.</span>length <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
